  "explain": "📖 교재 근거 (교재: L2435):\n소비자로부터 문서화되거나 구두로 표현된 불만에 대한 접수부터 조치까지의 일련의 절차가 확립되어야 하며, 불만처리담당자는 제품에 대한 모든 불만을 취합한다. 제기된 불만에 대해 신속하게 조사하고 그에 대한 적절한 조치를 취해야 하며, 다음 사항을 기록·유지하여야 한다.",
